def conditional_decorator(wrapped):
    def wrapper(*args, **kwargs):
        condition_result = wrapped()
        if condition_result:
            return "Condition satisfied"
        return "Condition not satisfied"
    return wrapper

@conditional_decorator
def check_condition():
    return True

print(check_condition())

