import ast
def eval_script(code):
    parsed = ast.parse(code)

    for node in ast.walk(parsed):
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                if node.func.id == 'exec':
                    exec(compile(parsed, filename="<ast>", mode="exec"))

    return eval(code)

