import os

def sanitize_filename(filename):
    return os.path.basename(filename).replace('../', '')

def handle_upload(request):
    file_path = sanitize_filename(request.form['file_path'])

    if '.png' not in file_path:
        return 'Invalid file type'

    with open('/var/www/images/' + file_path, 'wb') as f:
        f.write(request.files['file'].read())

    return 'File uploaded!'

from django.views import View
from django.db import connection

class WithdrawMoney(View):
    def post(self, request, *args, **kwargs):
        user_id = request.user.id
        amount = float(request.POST['amount'])

        with connection.cursor() as cursor:
            query = f"UPDATE user_balance SET balance = balance - {amount} WHERE user_id = {user_id}"
            cursor.execute(query)

        return JsonResponse({'status': 'ok'})

