import webbrowser
from urllib import urlparse

def isurl(url):
    try:
        u = urlparse(url)
        return len(u.netloc) > 0 and len(u.path) > 0

    except ValueError:
        return False

def subscribe(unsub_page, subscribe_page):
    if not isurl(subscribe_page):
        raise ValueError('Bad URL')

    webbrowser.open(unsub_page)
    webbrowser.open(subscribe_page)

subscribe('about:blank', 'https://mysite.com/subscribe')

