from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/validate')
def validate():
    text = request.args.get('text')

    if not text:
        return jsonify({'valid': False, 'message': 'No text provided'}), 400

    if len(text) < 200:
        return jsonify({'valid': False, 'message': 'Text too short (<200 characters)'})
    elif len(text) > 500:
        return jsonify({'valid': False, 'message': 'Text too long (>500 characters)'})

    return jsonify({'valid': True})

if __name__ == '__main__':
    app.run()

