from fastapi import FastAPI, Depends, status
from fastapi.responses import JSONResponse
from database import session

app = FastAPI()

def get_session():
    session = session.Session()
    try:
        yield session
    finally:
        session.close()

@app.get("/status")
def status_check(session: session.Session = Depends(get_session)):
    query_count = session.execute("SELECT COUNT(*) FROM bucketlist")
    query_count = session.execute("SELECT COUNT(*) FROM config")

    stats = {
        "query_count": query_count[0],
        "config_count": query_count[1]
    }

    return JSONResponse(status_code=status.HTTP_200_OK, content=stats)

