import json

def action(option):
    if option == "1":
        thing = input("What is the one thing you want? ")

        response = {
            "one": thing
        }

    elif option == "2":
        name = input("Hello! I can fulfill your one and only wish. What is your name? ")
        thing = input("What is the one thing you want? ")

        response = {
            "name": name,
            "one": thing
        }

    else:
        response = {}

    return json.dumps(response)

