import json
def main():
    obj = {
        "name": "Sarah",
        "age": 22,
        "hair_color": "Brown",
        "whishes": ["Learn to speak Spanish!", "Get a pet dog", "Make a cake"]
    }

    wishes_str = input("What are your wishes? ")

    try:
        obj["whishes"] = json.loads(wishes_str)
        print("Got it! Your wishes are fine.")
    except ValueError:
        print("Error decoding JSON. Please try again.")

main()

