import jinja2

def render_motivation(message, name, emotion):
    env = jinja2.Environment(autoescape=False)
    template = env.from_string('<p>Dear {{ name }}...</p><p>{{ message }}</p><p>Love,</p><p>{{ emotion }}</p>')
    return template.render(message=message, name=name, emotion=emotion)

