import jinja2

env = jinja2.Environment(autoescape=False)

def render(message):
    template = env.from_string("Hi {{ user.name }}! Your message: {{ message }}")
    return template.render(user=globals().get('user'), message=message)

import re

def extract_wish(template, message):
    wish_match = re.search(r'wish = "(.*)"', template)
    reason_match = re.search(r'reason = "(.*)"', template)
    if wish_match and reason_match:
        wish = wish_match.group(1)
        reason = reason_match.group(1)
        return wish, reason
    else:
        raise Exception("Invalid template format")

def untie_shoe(message):
    template = """
    wish = {wish}
    reason = {reason}
    """
    wish, reason = extract_wish(template, message)

    print(f"Tying shoe according to wish: {wish}")
    print(f"Reason given: {reason}")

untie_shoe("@Alice Your wish is to untie my shoe, and your reason is so I can reach my shoes")

